UPDATE `item_template` AS `i`
INNER JOIN `coa_fabled_items` AS `f` ON `f`.`entry` = `i`.`entry`
INNER JOIN `item_dbc` AS `d` ON `d`.`ID` = `i`.`entry`
SET `i`.`Quality` = 3,
  `i`.`Flags` = `i`.`Flags` | 0x08000000, `i`.`bonding` = 1, `i`.`ItemLevel` = `f`.`ItemLevel`,
  `i`.`stat_type1` = `f`.`stat_type1`, `i`.`stat_value1` = `f`.`stat_value1`, `i`.`stat_type2` = `f`.`stat_type2`,
  `i`.`stat_value2` = `f`.`stat_value2`, `i`.`stat_type3` = `f`.`stat_type3`, `i`.`stat_value3` = `f`.`stat_value3`,
  `i`.`stat_type4` = `f`.`stat_type4`, `i`.`stat_value4` = `f`.`stat_value4`, `i`.`armor` = `f`.`armor`,
  `i`.`description` = '@Fabled@';

UPDATE `spell_dbc` AS `s`
INNER JOIN `coa_fabled_items` AS `f` ON `s`.`ID` = `f`.`entry` + 20000
INNER JOIN `item_dbc` AS `d` ON `d`.`ID` = `f`.`entry`
SET `s`.`Description_Lang_enUS` = `f`.`tooltip`;

DROP TEMPORARY TABLE `coa_fabled_items`;
